//! Complete init policy over actual hidden-inclusive CODE+MAPS original loans.
//! Two physical phases retain only compact table facts and report data.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_raw_file::Config,reactive_raw_policy_pages::RawPolicyPages,init_policy::{self,Def,Output},captured_allow_annotations::PatternOperation,key_policy_control::{self as kc,Control},lint::{Site,AllowUse}};
use std::{collections::{BTreeMap,BTreeSet},io,path::Path,sync::Arc};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}check(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
pub struct InitData{sites:Vec<Site>,source_text:Vec<String>,allows:Vec<AllowUse>,digests:BTreeMap<String,[u8;20]>}
impl InitData{
 pub fn metadata(&self)->&'static crate::lint::Meta{crate::lints::init::captured_metadata()}
 pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allows}pub fn notes(&self)->&[String]{&[]}pub fn allow_source_digest(&self,relative:&str)->Option<&[u8;20]>{self.digests.get(relative)}
 pub fn serialize_data<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::SerializeTuple;let mut rows=serializer.serialize_tuple(4)?;rows.serialize_element(&self.sites)?;rows.serialize_element(&self.source_text)?;rows.serialize_element(&self.allows)?;rows.serialize_element(&self.digests)?;rows.end()}
 pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?.checked_add(self.allows.capacity().checked_mul(std::mem::size_of::<AllowUse>())?)?;for s in &self.sites{for word in [&s.rule,&s.rel,&s.msg,&s.key,&s.ident]{n=n.checked_add(word.capacity())?}}for word in &self.source_text{n=n.checked_add(word.capacity())?}for a in &self.allows{for word in [&a.rel,&a.name,&a.code]{n=n.checked_add(word.capacity())?}}for path in self.digests.keys(){n=n.checked_add(2048)?.checked_add(path.capacity())?}Some(n)}
}
pub fn metadata()->&'static crate::lint::Meta{crate::lints::init::captured_metadata()}

pub fn selects_path(relative:&str)->bool{(relative.starts_with("code/")||relative.starts_with("maps/"))&&relative.ends_with(".dm")}
struct NativeOutput<'a>{file:&'a crate::tree::SourceFile,data:&'a mut InitData,local:&'a Budget,keep:&'a Budget,poll:&'a dyn Fn()->io::Result<()>,patterns:Option<&'a dyn crate::native_pattern::Provider>}
impl NativeOutput<'_>{fn emit(&mut self,rule:&'static str,line:usize,message:String,identity:String,text:Option<&str>)->Result<(),Failure>{let mut work=PatternOperation{budget:self.keep,poll:self.poll,patterns:self.patterns};work.checkpoint()?;self.keep.charge(message.capacity().checked_add(identity.capacity()).ok_or_else(||oom(self.keep,"init report strings overflow"))?).map_err(|m|oom(self.keep,m))?;kc::row(&mut work,&mut self.data.sites)?;self.data.sites.push(Site{rule:kc::own(&mut work,rule)?,rel:kc::own(&mut work,&self.file.rel)?,line:u32::try_from(line).map_err(|_|oom(self.keep,"init site line overflow"))?,msg:message,key:String::new(),ident:identity});let text=text.unwrap_or_else(||self.file.raw().line(line));kc::row(&mut work,&mut self.data.source_text)?;kc::reserve(&mut work,||text.len().checked_mul(4)?.checked_add(128))?;self.data.source_text.push(crate::util::normalize_ws(text));Ok(())}}
impl Output<Failure> for NativeOutput<'_>{fn site(&mut self,rule:&'static str,line:usize,message:String,identity:String)->Result<(),Failure>{self.emit(rule,line,message,identity,None)}fn allowed(&mut self,lines:&[&str],line:usize)->Result<bool,Failure>{let mut work=PatternOperation{budget:self.local,poll:self.poll,patterns:self.patterns};let mut found=None;for current in[Some(line),line.checked_sub(1).filter(|n|*n!=0)].into_iter().flatten(){work.checkpoint()?;let Some(text)=current.checked_sub(1).and_then(|index|lines.get(index))else{continue};if current!=line&&!crate::util::py_lstrip(text).starts_with("//"){continue}if let Some(code)=crate::allow::keeps_with(text,"init",&mut work)?{found=Some((current,code.unwrap_or_default()));break}}let Some((at,code))=found else{return Ok(false)};let mut held=PatternOperation{budget:self.keep,poll:self.poll,patterns:self.patterns};if !self.data.allows.iter().any(|a|a.rel==self.file.rel&&a.line as usize==at&&a.name=="init"&&a.code==code){kc::row(&mut held,&mut self.data.allows)?;self.keep.charge(code.capacity()).map_err(|m|oom(self.keep,m))?;self.data.allows.push(AllowUse{rel:kc::own(&mut held,&self.file.rel)?,line:u32::try_from(at).map_err(|_|oom(self.keep,"init ALLOW line overflow"))?,name:kc::own(&mut held,"init")?,code})}if !self.data.digests.contains_key(&self.file.rel){kc::reserve(&mut held,||Some(2048))?;self.data.digests.insert(kc::own(&mut held,&self.file.rel)?,crate::captured_raw_file::source_allow_digest(self.file));}Ok(true)}}
struct TableRow{relative:String,key:crate::dm::walk::WalkKey,facts:init_policy::TableFacts,text:Vec<String>}
pub fn collect_from_pages(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<InitData,Failure>{collect_using(inputs,root_path,pages,config,root,poll,None)}
pub fn collect_from_pages_with_patterns(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<InitData,Failure>{collect_using(inputs,root_path,pages,config,root,poll,Some(patterns))}
fn collect_using(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<InitData,Failure>{
 check(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&phase.budget;let pending=(||{
 let mut work=PatternOperation{budget,poll,patterns};let mut data=InitData{sites:Vec::new(),source_text:Vec::new(),allows:Vec::new(),digests:BTreeMap::new()};let mut tables=Vec::new();
 let judged=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;if !selects_path(relative){return Err("init source provider escaped hidden-inclusive CODE+MAPS".into())}if config.policy_path_exempt("init","",relative){return Ok(true)}let file=views.source_file()?;let mut temp=PatternOperation{budget:local,poll,patterns};kc::reserve(&mut temp,||file.raw().num_lines().checked_mul(4*std::mem::size_of::<&str>())?.checked_add(128))?;let lines:Vec<_>=(1..=file.raw().num_lines()).map(|n|file.raw().line(n).trim_end_matches('\r')).collect();let mut definitions:BTreeMap<usize,(Def,String,String)>=BTreeMap::new();
 dm_analysis::lifecycle_declarations::visit_lifecycle_definitions_using(inputs.archive(),dm_analysis::lifecycle_declarations::LifecyclePolicy::Init,&||check(local,poll),&|error|Failure::Unsupported(error.0),&mut|row|{
 temp.checkpoint()?;let origin=inputs.archive().callable_header_policy_line(row.member)?;let actual=inputs.file_exact(origin.path.as_path()).ok_or("init actual header has no current source")?;if !actual.is_compiled(){return Err("init actual header is not compiled source".into())}kc::reserve(&mut temp,||origin.path.as_os_str().len().checked_add(root_path.as_os_str().len())?.checked_mul(128)?.checked_add(4096))?;let Some(rel)=dm_preprocess::regions::relative_filesystem_path(origin.path.as_path(),root_path)else{return Ok(())};if rel.to_string_lossy().replace('\\',"/")!=relative{return Ok(())}let line=actual.analyze_display_line(origin.line).map_err(|e|Failure::Unsupported(e.to_string()))?;if line==0||line>lines.len(){return Err("init actual header cannot project original line".into())}let tree=inputs.archive().tree();let owner=tree.symbols().text(row.owner).ok_or("init actual owner unavailable")?;let name=tree.symbols().text(row.name).ok_or("init actual callable unavailable")?;let kind=match name{"Initialize"=>Def::Init,"LateInitialize"=>Def::Late,_=>Def::TurfMaterialize};if definitions.get(&line).is_none_or(|(_,old_owner,old_name)|(owner,name)>(old_owner.as_str(),old_name.as_str())){if !definitions.contains_key(&line){kc::reserve(&mut temp,||Some(2048))?;}definitions.insert(line,(kind,kc::own(&mut temp,owner)?,kc::own(&mut temp,name)?));}Ok(())
 })?;
 for(index,line)in lines.iter().enumerate(){temp.checkpoint()?;if let Some(kind)=init_policy::text_header_using(line,&mut temp)?{if !definitions.contains_key(&(index+1)){kc::reserve(&mut temp,||line.len().checked_mul(8)?.checked_add(2048))?;definitions.insert(index+1,(kind,init_policy::text_owner_using(line,&mut temp)?,String::new()));}}}
 for(header,(kind,owner,_))in definitions{temp.checkpoint()?;let mut is_root=false;if kind==Def::Init{if let Some(scope)=config.borrowed_report_scope("init",""){for entry in scope.list("init_roots"){temp.checkpoint()?;if entry.split_once(" = ").is_some_and(|(path,_)|path.trim()==owner){is_root=true;break}}}}if is_root{continue}init_policy::judge_definition_using(&lines,header,kind,&owner,&mut temp,&mut NativeOutput{file,data:&mut data,local,keep:budget,poll,patterns})?;}Ok(true)})();finish(pending,local,poll)})?;if !judged{return Err("init selected definition phase stopped before actual EOF".into())}
 let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(budget);let pending=(||{check(local,poll)?;if !selects_path(relative){return Err("init table provider escaped hidden-inclusive CODE+MAPS".into())}let file=views.source_file()?;let mut temp=PatternOperation{budget:local,poll,patterns};let mut output=NativeOutput{file,data:&mut data,local,keep:budget,poll,patterns};let facts=init_policy::table_facts_using(file,&mut temp,&mut|lines,line|output.allowed(lines,line))?;if !facts.flags.is_empty()||!facts.headers.is_empty(){let actual=facts.flags.capacity().checked_mul(std::mem::size_of::<(String,bool)>()).and_then(|n|n.checked_add(facts.headers.capacity().checked_mul(std::mem::size_of::<(u32,String)>())?)).and_then(|n|facts.flags.iter().try_fold(n,|n,(path,_)|n.checked_add(path.capacity()))).and_then(|n|facts.headers.iter().try_fold(n,|n,(_,path)|n.checked_add(path.capacity()))).ok_or_else(||oom(budget,"init table retained facts overflow"))?;budget.charge(actual).map_err(|m|oom(budget,m))?;let mut text=Vec::new();for(line,_)in &facts.headers{work.checkpoint()?;kc::row(&mut work,&mut text)?;text.push(kc::own(&mut work,file.raw().line(*line as usize))?);}kc::row(&mut work,&mut tables)?;tables.push(TableRow{relative:kc::own(&mut work,relative)?,key:crate::dm::walk::walk_key_using(relative,&mut work)?,facts,text});}Ok(true)})();finish(pending,local,poll)})?;if !complete{return Err("init table facts stopped before actual all-source EOF".into())}
 kc::reserve(&mut work,||tables.len().checked_mul(4*std::mem::size_of::<TableRow>())?.checked_add(128))?;let mut sort_error=None;tables.sort_by(|a,b|{if sort_error.is_some(){return crate::dm::walk::cmp_keys(&a.key,&b.key)}match crate::dm::walk::cmp_keys_using(&a.key,&b.key,&mut work){Ok(order)=>order,Err(actual)=>{sort_error=Some(actual);crate::dm::walk::cmp_keys(&a.key,&b.key)}}});if let Some(actual)=sort_error{return Err(actual)}let mut flags:BTreeMap<&str,bool>=BTreeMap::new();for row in &tables{for(path,on)in &row.facts.flags{work.checkpoint()?;if !flags.contains_key(path.as_str()){kc::reserve(&mut work,||Some(2048))?;}flags.insert(path,*on);}}
 for row in &tables{for(index,(line,path))in row.facts.headers.iter().enumerate(){work.checkpoint()?;if init_policy::table_violation_using(path,&|ancestor|flags.get(ancestor).copied(),&mut work)?{kc::row(&mut work,&mut data.sites)?;data.sites.push(Site{rule:kc::own(&mut work,"table_init_overrides")?,rel:kc::own(&mut work,&row.relative)?,line:*line,msg:String::new(),key:String::new(),ident:String::new()});kc::row(&mut work,&mut data.source_text)?;let text=&row.text[index];kc::reserve(&mut work,||text.len().checked_mul(4)?.checked_add(128))?;data.source_text.push(crate::util::normalize_ws(text));}}}check(budget,poll)?;Ok(data)
 })();let pending=finish(pending,budget,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"init returned backing overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)
}
